import React, { useEffect } from 'react';
import './HowItWorks.css';
import Header from './Header';
import Footer from './Footer';
import banner1 from '../search.png';
import banner2 from '../reservespot.png'
import banner3 from '../pay.png'
import banner4 from '../parkgo.png'

function HowItWorks() {
  const steps = [
    {
      title: "Search for Parking",
      description:
        "Use our app to find available parking spots near your destination",
      icon: "https://cdn-icons-png.flaticon.com/512/684/684908.png",
      banner: banner1
    },
    {
      title: "Reserve Your Spot",
      description:
        "Select a spot and reserve it for your desired time period",
      icon: "https://cdn-icons-png.flaticon.com/512/747/747310.png",
      banner: banner2
    },
    {
      title: "Pay Securely",
      description: "Complete payment through our secure gateway",
      icon: "https://cdn-icons-png.flaticon.com/512/2331/2331941.png",
      banner: banner3
    },
    {
      title: "Park and Go",
      description:
        "Arrive at your reserved spot and enjoy hassle free",
      icon: "https://cdn-icons-png.flaticon.com/512/741/741407.png",
      banner: banner4
    }
  ];
  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
        } else {
          entry.target.classList.remove('visible');
        }
      });
    }, { threshold: 0.1 });

    const sections = document.querySelectorAll('section');

    sections.forEach(section => observer.observe(section));

    return () => {
      sections.forEach(section => observer.unobserve(section));
    };
  }, []);

  return (
    <div className="HowItWorks">
      <Header />
      <main>
        <section className="how-container">
          <h1>HOW IT WORKS</h1>
          <p className="how-subtitle">
            Discover the simple steps to reserve your parking spot with our Smart
            Parking System.
          </p>


          <div className="steps-wrapper">
            {steps.map((step, index) => (
              <div className="step-card" key={index}>
                <div className="icon-circle">
                  <img src={step.icon} alt={step.title} />
                </div>
                <h3>{step.title}</h3>
                <div className='banner-img'>
                  <img src={step.banner} alt={step.title} />
                </div>
                <p>{step.description}</p>
              </div>
            ))}
          </div>
        </section>
      </main>
      <Footer />
    </div>
  );
}

export default HowItWorks;
