import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext'; // Import our hook
import logo from '../sps.png';
import './Header.css';

function Header() {
    const { user, logout, loading } = useAuth(); // Get global user state
    const [isOpen, setIsOpen] = useState(false);
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const navigate = useNavigate();

    const toggleMenu = () => setIsOpen(!isOpen);
    const toggleDropdown = () => setIsDropdownOpen(!isDropdownOpen);
    
    const handleLogout = () => {
        logout();
        setIsDropdownOpen(false);
        navigate('/Auth');
    };

    return (
        <header className="appHeader">
            {/* Left Navigation */}
            <nav className="left-nav">
                <ul className="navbar-nav">
                    <li><Link to="/">Home</Link></li>
                    <li><Link to="/Booking">Booking</Link></li>
                    <li><Link to="/HowItWorks">How it works</Link></li>
                    <li><Link to="/Features">Features</Link></li>
                </ul>
            </nav>

            {/* Logo Section */}
            <div className="logoContainer">
                <Link to="/">
                    <img src={logo} alt="Logo" className="logo" />
                </Link>
                <span className="full-text">Smart Parking System</span>
                <span className="short-text">SPS</span>
            </div>

            {/* Right Navigation */}
            <nav className="right-nav">
                <ul className="navbar-nav">
                    <li><Link to="/Pricing">Pricing</Link></li>
                    <li><Link to="/About">About</Link></li>
                    <li><Link to="/Contact">Contact</Link></li>
                    
                    {/* Conditional Rendering based on DB Auth */}
                    {loading ? (
                        <li className="nav-loading">...</li>
                    ) : user ? (
                        <li className="profile-container">
                            <div className="profile-trigger" onClick={toggleDropdown}>
                                <span className="user-name">{user.name}</span>
                                <img 
                                    src={user.avatar || 'https://via.placeholder.com/35'} 
                                    alt="User" 
                                    className="avatar" 
                                />
                            </div>
                            
                            {isDropdownOpen && (
                                <div className="dropdown-box">
                                    <Link to="/Dashboard" onClick={() => setIsDropdownOpen(false)}>User Dashboard</Link>
                                    <button onClick={handleLogout} className="logout-btn">Logout</button>
                                </div>
                            )}
                        </li>
                    ) : (
                        <li><Link to="/Auth" className="auth-link">Auth</Link></li>
                    )}
                </ul>
            </nav>

            {/* Mobile Nav Logic */}
            <nav className={`mobile-nav ${isOpen ? 'open' : ''}`}>
                 <ul className="mobile-navbar-nav">
                    <li><Link to="/" onClick={toggleMenu}>Home</Link></li>
                    {user ? (
                        <>
                            <li><Link to="/Dashboard" onClick={toggleMenu}>Dashboard</Link></li>
                            <li><button onClick={handleLogout} className="mobile-logout">Logout</button></li>
                        </>
                    ) : (
                        <li><Link to="/Auth" onClick={toggleMenu}>Auth</Link></li>
                    )}
                 </ul>
            </nav>

            <button className="hamburger" onClick={toggleMenu}>
                <div className="bar"></div>
                <div className="bar"></div>
                <div className="bar"></div>
            </button>
        </header>
    );
}

export default Header;